import React, { useState, useEffect } from 'react';
import axios from 'axios';

const InteractiveSeating = ({ eventId }) => {
    const [seats, setSeats] = useState([]);

    useEffect(() => {
        axios.get(`/api/v1/events/${eventId}/seats`)
             .then(res => setSeats(res.data))
             .catch(err => console.error("Error fetching seats:", err));
    }, [eventId]);

    const handleSeatSelect = async (seatId) => {
        try {
            await axios.post(`/api/v1/seats/${seatId}/lock`);
            setSeats(seats.map(seat => 
                seat.id === seatId ? { ...seat, status: 'LOCKED' } : seat
            ));
            alert("Seat locked for 5 minutes. Proceed to checkout.");
        } catch (error) {
            alert("Seat is no longer available.");
        }
    };

    return (
        <div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
            {seats.map(seat => (
                <button 
                    key={seat.id}
                    disabled={seat.status !== 'AVAILABLE'}
                    style={{ 
                        padding: '15px 20px',
                        backgroundColor: seat.status === 'AVAILABLE' ? '#4CAF50' : '#FFC107',
                        color: '#000',
                        border: 'none',
                        borderRadius: '5px',
                        cursor: seat.status === 'AVAILABLE' ? 'pointer' : 'not-allowed'
                    }}
                    onClick={() => handleSeatSelect(seat.id)}
                >
                    {seat.seatIdentifier} ({seat.status})
                </button>
            ))}
        </div>
    );
};

export default InteractiveSeating;
